CREATE TABLE r15_discovery_batch (batch_id TEXT PRIMARY KEY, query_sha TEXT NOT NULL, provider TEXT NOT NULL, query_literal TEXT NOT NULL, raw_sha TEXT, result_state TEXT NOT NULL, created_utc TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE r15_paper_hit (hit_id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES r15_discovery_batch(batch_id), pmcid TEXT, doi TEXT, pmid TEXT, openalex_id TEXT, title TEXT, year INTEGER, metadata_sha TEXT NOT NULL, access_state TEXT NOT NULL);
CREATE TABLE r15_acquisition_attempt (attempt_id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES r15_discovery_batch(batch_id), hit_id TEXT, original_sha TEXT, source_path TEXT, provider TEXT, url TEXT, http_status INTEGER, acquisition_state TEXT NOT NULL, hold_reason TEXT);
CREATE TABLE r15_native_table_context (contrast_id TEXT PRIMARY KEY REFERENCES contrast_proposal(contrast_id), original_author_sha TEXT NOT NULL, unit_original TEXT, unit_semantic TEXT, unit_source_anchor TEXT, statistic_type TEXT, statistic_source_anchor TEXT, experiment_condition TEXT, condition_source_anchor TEXT, missing_fields_json TEXT NOT NULL, science_state TEXT NOT NULL DEFAULT 'SCI_REVIEW_HOLD' CHECK(science_state='SCI_REVIEW_HOLD'), training_approved INTEGER NOT NULL DEFAULT 0 CHECK(training_approved=0));
